import { isDebitNormal } from './accounts.js';
/* ------------------------------------------------------------------------ */
/* Saldo                                                                     */
/* ------------------------------------------------------------------------ */
/** Menyusun peta saldo dari baris terposting untuk rentang periode. Nilai bertanda sisi normal. */
export function balancesFromLines(lines, from, to) {
    const res = {};
    const ensure = (code) => (res[code] ||= { code, opening: 0, debit: 0, credit: 0, ending: 0 });
    for (const l of lines) {
        if (l.date > to)
            continue;
        const b = ensure(l.account);
        const signed = isDebitNormal(l.account) ? l.debit - l.credit : l.credit - l.debit;
        if (l.date < from)
            b.opening += signed;
        else {
            b.debit += l.debit;
            b.credit += l.credit;
        }
    }
    for (const b of Object.values(res))
        b.ending = b.opening + (isDebitNormal(b.code) ? b.debit - b.credit : b.credit - b.debit);
    return res;
}
/** Menyusun peta saldo dari agregat SQL: baris {code, openingDebit, openingCredit, debit, credit}. */
export function balancesFromAggregates(rows) {
    const res = {};
    for (const r of rows) {
        const dn = isDebitNormal(r.code);
        const opening = dn ? r.openingDebit - r.openingCredit : r.openingCredit - r.openingDebit;
        const ending = opening + (dn ? r.debit - r.credit : r.credit - r.debit);
        res[r.code] = { code: r.code, opening, debit: r.debit, credit: r.credit, ending };
    }
    return res;
}
export function sumBalances(maps) {
    const res = {};
    for (const m of maps)
        for (const b of Object.values(m)) {
            const t = (res[b.code] ||= { code: b.code, opening: 0, debit: 0, credit: 0, ending: 0 });
            t.opening += b.opening;
            t.debit += b.debit;
            t.credit += b.credit;
            t.ending += b.ending;
        }
    return res;
}
const side = (code, v) => {
    const dn = isDebitNormal(code);
    if (dn)
        return v >= 0 ? { d: v, k: 0 } : { d: 0, k: -v };
    return v >= 0 ? { d: 0, k: v } : { d: -v, k: 0 };
};
/* ------------------------------------------------------------------------ */
/* Neraca saldo                                                              */
/* ------------------------------------------------------------------------ */
export function trialBalance(accounts, bal) {
    const rows = accounts.details()
        .filter((a) => !a.isComputed)
        .map((a) => {
        const b = bal[a.code] ?? { opening: 0, debit: 0, credit: 0, ending: 0 };
        return { code: a.code, name: a.name, category: a.category, interco: a.isIntercompany, open: side(a.code, b.opening), debit: b.debit, credit: b.credit, end: side(a.code, b.ending) };
    })
        .filter((r) => r.open.d || r.open.k || r.debit || r.credit || r.end.d || r.end.k);
    const sum = (f) => rows.reduce((s, r) => s + f(r), 0);
    const totals = { openD: sum((r) => r.open.d), openK: sum((r) => r.open.k), debit: sum((r) => r.debit), credit: sum((r) => r.credit), endD: sum((r) => r.end.d), endK: sum((r) => r.end.k) };
    return { rows, totals, balanced: Math.abs(totals.endD - totals.endK) < 1 };
}
/** Pengelompokan laba rugi diturunkan dari struktur bagan akun (kode & induk). */
export const PL_GROUPS = [
    { id: 'pendapatan', label: 'Pendapatan', match: (a) => a.code.startsWith('4') && a.code !== '4-3000', sign: 1 },
    { id: 'hpp', label: 'Harga pokok penjualan', match: (a) => /^5-1/.test(a.code), sign: -1 },
    { id: 'opex', label: 'Beban operasional', match: (a) => a.parentCode === '5-2000', sign: -1 },
    { id: 'ga', label: 'Beban umum & administrasi', match: (a) => a.parentCode === '5-3000', sign: -1 },
    { id: 'lain', label: 'Pendapatan (beban) lain-lain', match: (a) => a.code === '4-3000' || /^5-4/.test(a.code), sign: 1 },
];
/** Nilai periode per akun laba rugi; positif = menambah laba. */
export function plAmounts(accounts, bal) {
    const amt = {};
    for (const a of accounts.details()) {
        if (!/^[45]/.test(a.code))
            continue;
        const b = bal[a.code];
        const mut = b ? (a.code.startsWith('4') ? b.credit - b.debit : b.debit - b.credit) : 0;
        amt[a.code] = a.code.startsWith('4') ? mut : -mut;
    }
    return amt;
}
export function incomeStatement(accounts, bal) {
    const amt = plAmounts(accounts, bal);
    const groupAccounts = (g) => accounts.details().filter((a) => g.match(a) && !a.isComputed);
    const g = (id) => { const grp = PL_GROUPS.find((x) => x.id === id); return groupAccounts(grp).reduce((s, a) => s + (amt[a.code] || 0), 0); };
    const revenue = g('pendapatan'), cogs = -g('hpp'), gross = revenue - cogs;
    const opex = -g('opex'), ga = -g('ga'), operating = gross - opex - ga;
    const other = g('lain'), net = operating + other;
    return {
        groups: PL_GROUPS.map((grp) => ({
            id: grp.id, label: grp.label,
            rows: groupAccounts(grp).map((a) => ({ code: a.code, name: a.name, amount: grp.sign * (amt[a.code] || 0) })).filter((r) => r.amount),
        })),
        amounts: amt, revenue, cogs, gross, opex, ga, operating, other, net,
        grossMargin: revenue ? (gross / revenue) * 100 : 0,
        netMargin: revenue ? (net / revenue) * 100 : 0,
    };
}
/** Laba (rugi) sejak awal tahun buku: Σ pendapatan − Σ beban dari saldo s.d. akhir periode (opening + mutasi). */
export function ytdProfit(accounts, bal) {
    let p = 0;
    for (const a of accounts.details()) {
        const b = bal[a.code];
        if (!b)
            continue;
        if (a.code.startsWith('4'))
            p += b.ending;
        else if (a.code.startsWith('5'))
            p -= b.ending;
    }
    return p;
}
/* ------------------------------------------------------------------------ */
/* Neraca                                                                    */
/* ------------------------------------------------------------------------ */
export function balanceSheet(accounts, bal, asOf) {
    const section = (prefix) => accounts.details()
        .filter((a) => a.code.startsWith(prefix) && !a.isComputed)
        .map((a) => ({ code: a.code, name: a.name, amount: bal[a.code]?.ending ?? 0, parentCode: a.parentCode, interco: a.isIntercompany }))
        .filter((r) => r.amount);
    const assets = section('1'), liabilities = section('2'), equity = section('3');
    const profit = ytdProfit(accounts, bal);
    const sum = (rows) => rows.reduce((s, r) => s + r.amount, 0);
    const totalAssets = sum(assets), totalLiab = sum(liabilities), totalEquity = sum(equity) + profit;
    return {
        asOf, assets, liabilities, equity, profit,
        totalAssets, totalLiab, totalEquity, totalLiabEquity: totalLiab + totalEquity,
        currentAssets: sum(assets.filter((r) => r.parentCode === '1-1000')),
        fixedAssets: sum(assets.filter((r) => r.parentCode === '1-2000')),
        balanced: Math.abs(totalAssets - (totalLiab + totalEquity)) < 1,
    };
}
/* ------------------------------------------------------------------------ */
/* Konsolidasi                                                               */
/* ------------------------------------------------------------------------ */
export function consolidate(accounts, perBranch, build) {
    const combinedBal = sumBalances(perBranch.map((p) => p.balances));
    const eliminations = accounts.list
        .filter((a) => a.isIntercompany)
        .map((a) => ({ code: a.code, name: a.name, amount: combinedBal[a.code]?.ending ?? 0 }))
        .filter((e) => e.amount);
    return {
        columns: perBranch.map((p) => ({ branch: p.branch, label: p.label, report: build(p.balances) })),
        combined: build(combinedBal),
        eliminations,
    };
}
/** Selisih eliminasi: RK Cabang (pusat) harus sama dengan Σ RK Kantor Pusat (cabang). */
export function intercompanyMismatch(accounts, combined) {
    const debitSide = accounts.list.filter((a) => a.isIntercompany && isDebitNormal(a.code)).reduce((s, a) => s + (combined[a.code]?.ending ?? 0), 0);
    const creditSide = accounts.list.filter((a) => a.isIntercompany && !isDebitNormal(a.code)).reduce((s, a) => s + (combined[a.code]?.ending ?? 0), 0);
    return debitSide - creditSide;
}
